WITH enriched AS (SELECT id, promo_code, starts_on, ends_on, discount_pct, LEAD(discount_pct, 2) OVER (ORDER BY starts_on ASC, id ASC) AS next_discount_pct, MAX(discount_pct) OVER (PARTITION BY channel) AS channel_max_discount_pct, NTILE(5) OVER w_ordered AS discount_pct_bucket, NTILE(3) OVER w_ordered AS discount_pct_bucket_2 FROM promotions WINDOW w_ordered AS (ORDER BY discount_pct DESC, id ASC)) SELECT id, discount_pct, next_discount_pct, channel_max_discount_pct, discount_pct_bucket_2 FROM enriched
